#include <WiFiClientSecure.h>
#include <PubSubClient.h>

extern const char rootCa[];  // Define with your trusted CA.
WiFiClientSecure tls;
PubSubClient mqtt(tls);
unsigned long retryAt = 0;

void setup() {
  Serial.begin(115200);
  tls.setCACert(rootCa);
  mqtt.setServer("broker.example.org", 8883);
}

void loop() {
  if (!mqtt.connected() && millis() - retryAt > 5000) {
    retryAt = millis();
    if (!mqtt.connect("sensor-01", "DEVICE_USER", "DEVICE_TOKEN")) {
      Serial.println("Broker connection failed");
    }
  }
  if (mqtt.connected()) {
    mqtt.loop();
    if (!mqtt.publish("lab/sensor/reading", "23.5")) {
      Serial.println("Publish failed");
    }
  }
  delay(1000);
}
